    .wh-olm {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100%;
  min-height: 0;
  padding: 20px 24px;
  background: #ffffff;
  border-radius: 8px;
  border: 1px solid #e8ecf1;
  box-sizing: border-box;
}

.wh-olm-main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 32px;
  min-height: 0;
  flex: 1;
}

.wh-olm-left {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
  min-width: 0;
}

.wh-olm-greeting {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex-wrap: wrap;
}

.wh-olm-name {
  font-size: 20px;
  font-weight: 600;
  color: #0d1b2a;
  line-height: 1.3;
  margin: 0;
}

.wh-olm-welcome {
  font-size: 14px;
  color: #5a6a7a;
  line-height: 1.4;
}

.wh-olm-mainline {
  font-size: 13px;
  color: #2563eb;
  line-height: 1.5;
  margin: 0;
  padding: 6px 10px;
  background: #eff6ff;
  border-radius: 6px;
  border-left: 3px solid #2563eb;
}

.wh-olm-right {
  display: flex;
  gap: 28px;
  flex-shrink: 0;
}

.wh-olm-metric {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 120px;
}

.wh-olm-label {
  font-size: 12px;
  color: #8a94a6;
  line-height: 1.4;
  white-space: nowrap;
}

.wh-olm-value {
  font-size: 18px;
  font-weight: 600;
  color: #0d1b2a;
  line-height: 1.3;
  white-space: nowrap;
}

.wh-olm-actions {
  display: flex;
  gap: 10px;
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid #f0f2f5;
}

.wh-olm-btn {
  padding: 8px 20px;
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.15s ease;
}

.wh-olm-btn-primary {
  background: #2563eb;
  color: #ffffff;
}

.wh-olm-btn-primary:hover {
  background: #1d4ed8;
}

.wh-olm-btn-secondary {
  background: #f1f5f9;
  color: #334155;
  border: 1px solid #e2e8f0;
}

.wh-olm-btn-secondary:hover {
  background: #e2e8f0;
}

@media (max-width: 640px) {
  .wh-olm {
    padding: 16px;
  }

  .wh-olm-main {
    flex-direction: column;
    gap: 16px;
  }

  .wh-olm-right {
    width: 100%;
    justify-content: space-between;
    gap: 16px;
  }

  .wh-olm-metric {
    min-width: 0;
    flex: 1;
  }

  .wh-olm-value {
    font-size: 16px;
  }

  .wh-olm-actions {
    flex-direction: column;
    gap: 8px;
  }

  .wh-olm-btn {
    width: 100%;
    padding: 10px 16px;
  }
}

.ai-html-copytrade-signals {
  --ai-primary: #0d6efd;
  --ai-primary-hover: #0b5ed7;
  --ai-success: #198754;
  --ai-danger: #dc3545;
  --ai-warning: #f59e0b;
  --ai-text: #1a1a2e;
  --ai-text-secondary: #6b7280;
  --ai-text-muted: #9ca3af;
  --ai-bg: #f8fafc;
  --ai-card-bg: #ffffff;
  --ai-border: #e5e7eb;
  --ai-border-light: #f1f5f9;
  --ai-radius: 6px;
  --ai-radius-sm: 4px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--ai-bg);
  border-radius: var(--ai-radius);
  padding: 16px;
  width: 100%;
  box-sizing: border-box;
}

.ai-signals-header {
  margin-bottom: 12px;
}

.ai-signals-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.ai-signals-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ai-text);
  margin: 0;
  line-height: 1.4;
}

.ai-signals-more {
  font-size: 12px;
  color: var(--ai-primary);
  text-decoration: none;
  font-weight: 500;
  transition: color 0.15s ease;
}

.ai-signals-more:hover {
  color: var(--ai-primary-hover);
}

.ai-signals-indicator {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--ai-text-secondary);
}

.ai-indicator-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ai-success);
  flex-shrink: 0;
}

.ai-indicator-divider {
  color: var(--ai-text-muted);
}

.ai-signals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.ai-signal-card {
  background: var(--ai-card-bg);
  border: 1px solid var(--ai-border);
  border-radius: var(--ai-radius);
  padding: 14px;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.ai-signal-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  min-height: 0;
}

.ai-signal-name {
  font-size: 14px;
  font-weight: 600;
  color: var(--ai-text);
  line-height: 1.3;
}

.ai-risk-tag {
  font-size: 11px;
  font-weight: 500;
  padding: 2px 8px;
  border-radius: var(--ai-radius-sm);
  flex-shrink: 0;
}

.ai-risk-low {
  background: #ecfdf5;
  color: var(--ai-success);
}

.ai-risk-mid {
  background: #fffbeb;
  color: #b45309;
}

.ai-risk-high {
  background: #fef2f2;
  color: var(--ai-danger);
}

.ai-signal-metrics {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}

.ai-metric {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ai-metric-label {
  font-size: 12px;
  color: var(--ai-text-secondary);
  line-height: 1.3;
}

.ai-metric-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--ai-text);
  line-height: 1.3;
  font-variant-numeric: tabular-nums;
}

.ai-value-up {
  color: var(--ai-success);
}

.ai-value-down {
  color: var(--ai-danger);
}

.ai-signal-chart {
  margin-bottom: 10px;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.ai-chart-tabs {
  display: flex;
  gap: 2px;
  margin-bottom: 6px;
}

.ai-chart-tab {
  font-size: 11px;
  padding: 2px 8px;
  border-radius: var(--ai-radius-sm);
  color: var(--ai-text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
  line-height: 1.4;
}

.ai-chart-tab-active {
  background: var(--ai-border-light);
  color: var(--ai-text-secondary);
  font-weight: 500;
}

.ai-chart-area {
  flex: 1;
  min-height: 48px;
  position: relative;
}

.ai-chart-svg {
  width: 100%;
  height: 100%;
  color: var(--ai-primary);
}

.ai-signal-action {
  width: 100%;
  padding: 8px 0;
  border-radius: var(--ai-radius-sm);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.15s ease;
  border: none;
  line-height: 1.4;
  margin-top: auto;
}

.ai-action-primary {
  background: var(--ai-primary);
  color: #fff;
}

.ai-action-primary:hover {
  background: var(--ai-primary-hover);
}

.ai-action-followed {
  background: transparent;
  color: var(--ai-text-secondary);
  border: 1px solid var(--ai-border);
}

.ai-action-followed:hover {
  background: var(--ai-border-light);
}

@media (max-width: 768px) {
  .ai-signals-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .ai-html-copytrade-signals {
    padding: 12px;
  }

  .ai-signal-card {
    padding: 12px;
  }

  .ai-chart-area {
    min-height: 56px;
  }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .ai-signals-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

