  flex: 1;
  display: flex;
  flex-direction: row;
  gap: 24px;
  border-left: 1px solid #f1f5f9;
  border-right: 1px solid #f1f5f9;
  padding: 0 24px;
}

.wh-status-item label {
  display: block;
  font-size: 12px;
  color: #94a3b8;
  margin-bottom: 4px;
}

.wh-status-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
}

.wh-status-tag.success {
  background: #f0fdf4;
  color: #16a34a;
}

.wh-status-tag.warning {
  background: #fffbeb;
  color: #d97706;
}

.wh-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.wh-dot.pulse {
  box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.4);
  animation: wh-pulse 2s infinite;
}

@keyframes wh-pulse {
  0% { box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.4); }
  70% { box-shadow: 0 0 0 6px rgba(22, 163, 74, 0); }
  100% { box-shadow: 0 0 0 0 rgba(22, 163, 74, 0); }
}

.wh-asset-col {
  flex: 1;
  text-align: right;
}

.wh-asset-label {
  font-size: 12px;
  color: #94a3b8;
}

.wh-asset-value {
  font-size: 20px;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.02em;
}

.wh-action-dock {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-top: 16px;
  border-top: 1px dashed #e2e8f0;
}

.wh-btn {
  height: 32px;
  padding: 0 12px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.2s;
  border: none;
}

.wh-btn-primary {
  background: #2563eb;
  color: #ffffff;
}

.wh-btn-primary:hover { background: #1d4ed8; }

.wh-btn-secondary {
  background: #f1f5f9;
  color: #475569;
}

.wh-btn-secondary:hover { background: #e2e8f0; }

.wh-btn-ghost {
  background: transparent;
  color: #64748b;
}

.wh-btn-ghost:hover { background: #f8fafc; }

.wh-btn-link {
  background: transparent;
  color: #2563eb;
  padding: 0 4px;
}

.wh-dock-divider {
  width: 1px;
  height: 16px;
  background: #e2e8f0;
  margin: 0 4px;
}

@media (max-width: 1024px) {
  .wh-main-content { gap: 16px; }
  .wh-status-col { padding: 0 16px; gap: 16px; }
}

@media (max-width: 768px) {
  .wh-main-content {
    flex-direction: column;
    align-items: flex-start;
    gap: 20px;
  }
  .wh-status-col {
    border: none;
    padding: 0;
    width: 100%;
    justify-content: flex-start;
  }
  .wh-asset-col {
    text-align: left;
  }
  .wh-action-dock {
    flex-wrap: wrap;
  }
