      "css": ".ct-signals-widget {
  --ct-bg: #ffffff;
  --ct-surface: #f8fafc;
  --ct-border: #e2e8f0;
  --ct-text: #0f172a;
  --ct-text-secondary: #64748b;
  --ct-text-muted: #94a3b8;
  --ct-accent: #2563eb;
  --ct-accent-hover: #1d4ed8;
  --ct-positive: #059669;
  --ct-negative: #dc2626;
  --ct-risk-low: #059669;
  --ct-risk-moderate: #d97706;
  --ct-risk-high: #dc2626;
  --ct-radius: 6px;
  --ct-gap: 16px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--ct-bg);
  border: 1px solid var(--ct-border);
  border-radius: var(--ct-radius);
  padding: 20px;
  width: 100%;
  box-sizing: border-box;
}

.ct-signals-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.ct-signals-title {
  font-size: 15px;
  font-weight: 600;
  color: var(--ct-text);
  margin: 0;
  line-height: 1.4;
}

.ct-signals-meta {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ct-signals-count {
  font-size: 12px;
  color: var(--ct-text-muted);
  font-weight: 400;
}

.ct-signals-more {
  font-size: 12px;
  color: var(--ct-accent);
  text-decoration: none;
  font-weight: 500;
}

.ct-signals-more:hover {
  color: var(--ct-accent-hover);
}

.ct-signals-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--ct-gap);
}

.ct-signal-card {
  background: var(--ct-surface);
  border: 1px solid var(--ct-border);
  border-radius: var(--ct-radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: border-color 0.15s ease;
}

.ct-signal-card:hover {
  border-color: #cbd5e1;
}

.ct-signal-card--featured {
  border-color: #bfdbfe;
  background: #f8fafc;
}

.ct-signal-card--featured:hover {
  border-color: #93c5fd;
}

.ct-signal-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.ct-signal-identity {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.ct-signal-avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--ct-accent);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ct-signal-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.ct-signal-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--ct-text);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ct-signal-type {
  font-size: 11px;
  color: var(--ct-text-muted);
  line-height: 1.4;
}

.ct-risk-tag {
  font-size: 10px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 4px;
  white-space: nowrap;
  flex-shrink: 0;
}

.ct-risk-tag--low {
  color: #065f46;
  background: #d1fae5;
}

.ct-risk-tag--moderate {
  color: #92400e;
  background: #fef3c7;
}

.ct-risk-tag--high {
  color: #991b1b;
  background: #fee2e2;
}

.ct-signal-metrics {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.ct-metric-primary {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ct-metric-value {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.ct-metric-value--positive {
  color: var(--ct-positive);
}

.ct-metric-value--negative {
  color: var(--ct-negative);
}

.ct-metric-label {
  font-size: 11px;
  color: var(--ct-text-muted);
  font-weight: 400;
}

.ct-metric-secondary {
  display: flex;
  gap: 16px;
}

.ct-metric-sub {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.ct-sub-label {
  font-size: 10px;
  color: var(--ct-text-muted);
}

.ct-sub-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--ct-text-secondary);
}

.ct-trend-container {
  height: 48px;
  background: var(--ct-bg);
  border: 1px solid var(--ct-border);
  border-radius: var(--ct-radius);
  overflow: hidden;
  position: relative;
}

.ct-trend-placeholder {
  width: 100%;
  height: 100%;
  position: relative;
}

.ct-trend-placeholder::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 100%;
  background: linear-gradient(to top, rgba(5, 150, 105, 0.08) 0%, transparent 60%);
}

.ct-trend-placeholder::after {
  content: '';
  position: absolute;
  bottom: 8px;
  left: 8px;
  right: 8px;
  height: 2px;
  background: repeating-linear-gradient(90deg, #cbd5e1 0px, #cbd5e1 2px, transparent 2px, transparent 6px);
  border-radius: 1px;
  opacity: 0.5;
}

.ct-trend-placeholder--volatile::before {
  background: linear-gradient(to top, rgba(217, 119, 6, 0.08) 0%, transparent 60%);
}

.ct-trend-placeholder--stable::before {
  background: linear-gradient(to top, rgba(37, 99, 235, 0.06) 0%, transparent 60%);
}

.ct-signal-dock {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.ct-btn {
  flex: 1;
  height: 32px;
  border-radius: var(--ct-radius);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.ct-btn--primary {
  background: var(--ct-accent);
  color: #fff;
}

.ct-btn--primary:hover {
  background: var(--ct-accent-hover);
}

.ct-btn--secondary {
  background: var(--ct-bg);
  color: var(--ct-text-secondary);
  border: 1px solid var(--ct-border);
}

.ct-btn--secondary:hover {
  background: var(--ct-surface);
  border-color: #cbd5e1;
}

@media (max-width: 720px) {
  .ct-signals-grid {
    grid-template-columns: 1fr;
  }

  .ct-signal-card {
    padding: 14px;
  }

  .ct-metric-value {
    font-size: 20px;
  }

  .ct-trend-container {
    height: 44px;
  }
}

@media (min-width: 721px) and (max-width: 1024px) {
  .ct-signals-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ct-signal-card:last-child {
    grid-column: 1 / -1;
    max-width: 50%;
    margin: 0 auto;
  }
