:root {
  --home-bg: #f8faff;
  --home-card-bg: #ffffff;
  --home-primary: #007bff;
  --home-primary-hover: #0056b3;
  --home-secondary: #6c757d;
  --home-text: #333333;
  --home-text-light: #666666;
  --home-border: #e0e6ed;
  --home-radius-sm: 6px;
  --home-radius-md: 10px;
  --home-shadow: 0 2px 10px rgba(0, 0, 0, 0.05);
}

.ai-html-page {
  font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
  background: var(--home-bg);
  color: var(--home-text);
  padding: 24px;
  display: grid;
  gap: 24px;
  max-width: 1400px;
  margin: 0 auto;
}

.ai-html-section {
  background: var(--home-card-bg);
  border-radius: var(--home-radius-md);
  box-shadow: var(--home-shadow);
  padding: 24px;
}

.ai-html-card-title {
  font-size: 1.2em;
  font-weight: 600;
  margin-bottom: 16px;
  color: var(--home-text);
}

.ai-html-button {
  padding: 10px 20px;
  border: none;
  border-radius: var(--home-radius-sm);
  cursor: pointer;
  font-size: 0.95em;
  font-weight: 500;
  transition: background-color 0.2s, color 0.2s;
}

.ai-html-button-primary {
  background: var(--home-primary);
  color: #fff;
}

.ai-html-button-primary:hover {
  background: var(--home-primary-hover);
}

.ai-html-button-secondary {
  background: #e9ecef;
  color: var(--home-secondary);
}

.ai-html-button-secondary:hover {
  background: #dae0e5;
}

.ai-html-button-small {
  padding: 6px 12px;
  font-size: 0.85em;
}

.ai-html-button-text {
  background: none;
  color: var(--home-primary);
  padding: 0;
  font-size: 0.9em;
}

.ai-html-button-text:hover {
  text-decoration: underline;
}

.ai-html-welcome-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 20px 24px;
  background: linear-gradient(90deg, #e0f2ff 0%, #ffffff 100%);
  border-bottom: 1px solid var(--home-border);
  box-shadow: none;
}

.ai-html-welcome-content .ai-html-greeting {
  font-size: 1.3em;
  font-weight: 600;
  margin-bottom: 4px;
}

.ai-html-welcome-content .ai-html-tip {
  font-size: 0.85em;
  color: var(--home-text-light);
}

.ai-html-hero {
  background: linear-gradient(135deg, #007bff, #0056b3);
  color: #fff;
  padding: 30px;
  text-align: center;
}

.ai-html-banner-tag {
  display: inline-block;
  background: rgba(255, 255, 255, 0.2);
  padding: 4px 10px;
  border-radius: var(--home-radius-sm);
  font-size: 0.8em;
  margin-bottom: 10px;
}

.ai-html-banner-title {
  font-size: 1.8em;
  margin-bottom: 8px;
  font-weight: 700;
}

.ai-html-banner-text {
  font-size: 1em;
  margin-bottom: 15px;
  opacity: 0.9;
}

.ai-html-banner-details span {
  display: inline-block;
  margin: 0 10px;
  font-size: 0.9em;
  font-weight: 500;
}

.ai-html-asset-overview {
  text-align: center;
}

.ai-html-total-assets {
  font-size: 2em;
  font-weight: 700;
  color: var(--home-primary);
  margin-bottom: 20px;
}

.ai-html-asset-details {
  display: flex;
  justify-content: space-around;
  margin-bottom: 20px;
  border-top: 1px solid var(--home-border);
  padding-top: 16px;
}

.ai-html-asset-item {
  text-align: center;
}

.ai-html-asset-item small {
  display: block;
  color: var(--home-text-light);
  margin-bottom: 4px;
}

.ai-html-asset-item strong {
  font-size: 1.1em;
  font-weight: 600;
}

.ai-html-asset-actions button {
  margin: 0 8px;
}

.ai-html-onboarding-guide {
  grid-column: span 1;
}

.ai-html-steps {
  display: flex;
  justify-content: space-between;
  margin-bottom: 20px;
  position: relative;
}

.ai-html-steps::before {
  content: '';
  position: absolute;
  top: 18px;
  left: 10%;
  right: 10%;
  height: 2px;
  background: var(--home-border);
  z-index: 0;
}

.ai-html-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  position: relative;
  z-index: 1;
  flex: 1;
}

.ai-html-step-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--home-border);
  color: var(--home-text-light);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  margin-bottom: 8px;
  transition: background-color 0.2s, color 0.2s;
}

.ai-html-step-done .ai-html-step-icon {
  background: #28a745;
  color: #fff;
}

.ai-html-step-current .ai-html-step-icon {
  background: var(--home-primary);
  color: #fff;
}

.ai-html-step p {
  font-size: 0.9em;
  color: var(--home-text-light);
}

.ai-html-step-done p, .ai-html-step-current p {
  color: var(--home-text);
}

.ai-html-quick-actions {
  grid-column: span 1;
}

.ai-html-action-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.ai-html-quick-action-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-decoration: none;
  color: var(--home-text);
  padding: 12px 0;
  border-radius: var(--home-radius-sm);
  transition: background-color 0.2s;
}

.ai-html-quick-action-item:hover {
  background: var(--home-bg);
}

.ai-html-quick-action-item svg {
  width: 24px;
  height: 24px;
  margin-bottom: 8px;
  color: var(--home-primary);
}

.ai-html-quick-action-item span {
  font-size: 0.9em;
}

.ai-html-kyc-status {
  text-align: center;
}

.ai-html-status-indicator {
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
}

.ai-html-status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #28a745;
  margin-right: 8px;
}

.ai-html-status-indicator p {
  font-weight: 600;
  color: #28a745;
}

.ai-html-kyc-text {
  font-size: 0.9em;
  color: var(--home-text-light);
  margin-bottom: 15px;
}

.ai-html-copytrading-signals {
  padding-bottom: 30px;
}

.ai-html-signals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 20px;
}

.ai-html-signal-card {
  background: var(--home-bg);
  border-radius: var(--home-radius-sm);
  padding: 18px;
  text-align: center;
  border: 1px solid var(--home-border);
}

.ai-html-signal-name {
  font-weight: 600;
  margin-bottom: 8px;
}

.ai-html-signal-roi {
  font-size: 1.5em;
  font-weight: 700;
  color: #28a745;
  display: block;
  margin-bottom: 4px;
}

.ai-html-signal-card small {
  color: var(--home-text-light);
  display: block;
  margin-bottom: 12px;
}

.ai-html-split-section {
